use crate::ciphers::xor_stream::cipher::xor_stream_encrypt;
use crate::ciphers::xor_stream::keys::xor_stream_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one encryption pass over `input_len` generated bytes.
pub fn xor_stream_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let key = xor_stream_default_key();
    let watch = Stopwatch::start();
    let sealed = xor_stream_encrypt(&data, key);
    std::hint::black_box(sealed.len());
    watch.elapsed_ns()
}
